const e = React.createElement;
const stagger = Math.round(0.4 * fps);
const fadeDur = Math.round(0.5 * fps);

const leftOpacity = interpolate(frame, [0, Math.max(1, fadeDur)], [0, 1], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
const leftX = interpolate(frame, [0, Math.max(1, fadeDur)], [-80, 0], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});

const rightOpacity = interpolate(frame, [stagger, Math.max(stagger + 1, stagger + fadeDur)], [0, 1], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
const rightX = interpolate(frame, [stagger, Math.max(stagger + 1, stagger + fadeDur)], [80, 0], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});

const cardW = width * 0.38;
const cardH = height * 0.52;
const gap = width * 0.05;

const makeCard = (modelName, role, color, opacity, tx) => {
  const glowAlpha = Math.round(opacity * 40).toString(16).padStart(2, '0');
  return e('div', {style: {
    width: cardW,
    height: cardH,
    background: D.surface,
    borderRadius: 24,
    border: '3px solid ' + color,
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    gap: 24,
    opacity: opacity,
    transform: 'translateX(' + tx + 'px)',
    boxShadow: '0 0 60px ' + color + glowAlpha + ', inset 0 0 30px ' + color + '11',
  }},
    e('div', {style: {
      fontFamily: D.font_display,
      fontSize: 52,
      fontWeight: 800,
      color: color,
      letterSpacing: 3,
      textAlign: 'center',
    }}, modelName),
    e('div', {style: {
      fontSize: 48,
      color: D.text_dim,
      lineHeight: 1,
      marginTop: -4,
      marginBottom: -4,
    }}, '\u2193'),
    e('div', {style: {
      fontFamily: D.font_display,
      fontSize: 36,
      fontWeight: 700,
      color: D.white,
      textTransform: 'uppercase',
      letterSpacing: 4,
      textAlign: 'center',
      lineHeight: 1.3,
    }}, role)
  );
};

const vsScale = spring({frame: frame - stagger - fadeDur, fps, config: {damping: D.spring_damping, stiffness: D.spring_stiffness}});
const vsOpacity = interpolate(vsScale, [0, 1], [0, 1], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});

return e('div', {style: {
  position: 'absolute',
  inset: 0,
  background: D.bg,
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  gap: gap,
}},
  makeCard('GPT-5.5', 'BRILLIANT\nINTERN', D.violet, leftOpacity, leftX),
  e('div', {style: {
    fontFamily: D.font_display,
    fontSize: 28,
    fontWeight: 700,
    color: D.text_dim,
    opacity: vsOpacity,
    transform: 'scale(' + vsScale + ')',
    letterSpacing: 2,
  }}, 'VS'),
  makeCard('CLAUDE 4.7', 'SENIOR\nENGINEER', D.cyan, rightOpacity, rightX)
);
